import { useSnackbar } from 'notistack'
import { useState } from 'react'
import { Helmet } from 'react-helmet-async'
import { useNavigate } from 'react-router'

import {
  Box,
  Button,
  Card,
  Container,
  type SelectChangeEvent,
  Stack,
  Typography,
  useMediaQuery,
  useTheme
} from '@mui/material'

import { CATEGORY_MAIN } from 'src/data/categories'

import ClubSettingsField from 'src/components/ClubSettingsField'
import PageTitleWrapper from 'src/components/PageTitleWrapper'

import { type CreateClubInfoRequestData, useCreateClub } from 'src/hooks/api/admin'

const ClubRegisterPage: React.FC = () => {
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const navigate = useNavigate()
  const { enqueueSnackbar } = useSnackbar()
  const createClub = useCreateClub()
  const [clubInformation, setClubInformation] = useState<CreateClubInfoRequestData>({
    name: '',
    description: '',
    categoryMain: CATEGORY_MAIN.OTHERS,
    categorySub: null,
    belonging: '',
    location: '',
    contactEmail: ''
  })

  const handleClubInformationChange: React.ChangeEventHandler<HTMLInputElement> = event => {
    const { name, value } = event.target
    setClubInformation(prevClubInformation => ({
      ...prevClubInformation,
      [name]: value
    }))
  }

  const handleClubCategorySelectedChange = (event: SelectChangeEvent<string>): void => {
    const { name, value } = event.target
    setClubInformation(prevClubInformation => ({
      ...prevClubInformation,
      [name]: value
    }))
  }

  const handleRegisterButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    if (
      !clubInformation.name ||
      !clubInformation.description ||
      !clubInformation.categoryMain ||
      !clubInformation.belonging
    ) {
      enqueueSnackbar('모든 정보를 입력해주세요', { variant: 'warning' })
      return
    }

    createClub.mutate(clubInformation)
  }

  const handleAdminButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin')
  }

  return (
    <>
      <Helmet>
        <title>동아리 등록 - KLUB</title>
      </Helmet>
      <PageTitleWrapper>
        <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" spacing={2}>
          <Box>
            <Typography variant={isMobile ? 'h4' : 'h3'}>동아리 등록</Typography>
            <Typography color="text.secondary" sx={{ mt: 1 }}>
              새 동아리의 기본 정보와 분류 정보를 입력합니다.
            </Typography>
          </Box>
          <Button variant="outlined" onClick={handleAdminButtonClick}>
            어드민 페이지
          </Button>
        </Stack>
      </PageTitleWrapper>
      <Container maxWidth="lg">
        <Card sx={{ p: { xs: 2, md: 3 }, boxShadow: theme.header.boxShadow }}>
          <ClubSettingsField
            clubInformation={clubInformation}
            handleChange={handleClubInformationChange}
            handleSelect={handleClubCategorySelectedChange}
            handleClickEditButton={handleRegisterButtonClick}
          />
        </Card>
      </Container>
    </>
  )
}

export default ClubRegisterPage
